/*
 * Deployment data for the /deploy page: the five contracts in order, their creation code with library
 * addresses written in, and the desk's constructor arguments. Generated bytecode comes from
 * artifacts.json (scripts/contracts-artifacts.mjs); nothing here signs or sends.
 */
import ARTIFACTS from "./artifacts.json";

export type ContractName = "QouraTwinHash" | "QouraChallengeTape" | "QouraConstraintSet" | "QouraRedeemCheck" | "QouraCreditDesk";
type Link = { lib: string; start: number; length: number };
type Artifact = { abi: unknown[]; creation: string; runtime: string; creationLinks: Link[]; runtimeLinks: Link[]; sha256: string };

const CONTRACTS = ARTIFACTS.contracts as unknown as Record<ContractName, Artifact>;
export const DEPLOY_ORDER = ARTIFACTS.deployOrder as ContractName[];
export const artifactOf = (name: ContractName) => CONTRACTS[name];

/** Libraries each contract needs, by name. */
export const linksOf = (name: ContractName) => [...new Set(CONTRACTS[name].creationLinks.map((l) => l.lib))] as ContractName[];

const isAddr = (a: string) => /^0x[0-9a-fA-F]{40}$/.test(a);

/** Creation code with every library placeholder replaced by its deployed address. */
export function linkedCreation(name: ContractName, libraries: Partial<Record<ContractName, string>>) {
  const a = CONTRACTS[name];
  let hex = a.creation.slice(2);
  for (const l of a.creationLinks) {
    const at = libraries[l.lib as ContractName];
    if (!at || !isAddr(at)) throw new Error(`${name} needs ${l.lib} deployed first`);
    hex = hex.slice(0, l.start * 2) + at.slice(2).toLowerCase() + hex.slice((l.start + l.length) * 2);
  }
  if (hex.includes("__$")) throw new Error(`${name} still has an unlinked library`);
  return `0x${hex}`;
}

/** QouraCreditDesk(usdg, treasury, verifier, initialOwner), ABI-encoded and appended to the creation code. */
export function deskDeployData(o: { libraries: Partial<Record<ContractName, string>>; usdg: string; treasury: string; verifier: string; owner: string }) {
  for (const [k, v] of Object.entries({ usdg: o.usdg, treasury: o.treasury, verifier: o.verifier, owner: o.owner })) {
    if (!isAddr(v) || /^0x0{40}$/.test(v)) throw new Error(`${k} must be a nonzero address`);
  }
  const w = (a: string) => a.slice(2).toLowerCase().padStart(64, "0");
  return linkedCreation("QouraCreditDesk", o.libraries) + w(o.usdg) + w(o.treasury) + w(o.verifier) + w(o.owner);
}

/** Deploy data for any step: libraries and the verifier take no constructor arguments. */
export function deployData(
  name: ContractName,
  o: { libraries: Partial<Record<ContractName, string>>; usdg?: string; treasury?: string; owner?: string },
) {
  if (name !== "QouraCreditDesk") return linkedCreation(name, o.libraries);
  const verifier = o.libraries.QouraRedeemCheck;
  if (!verifier || !o.usdg || !o.treasury || !o.owner) throw new Error("The desk needs USDG, the treasury, the verifier and the owner");
  return deskDeployData({ libraries: o.libraries, usdg: o.usdg, treasury: o.treasury, verifier, owner: o.owner });
}
